import {AiClient,mountChat} from '../components/index.js';
const $=id=>document.getElementById(id);let client,chat,session=null,items=[],counter=0;
const references=[{kind:'entity',id:'travel-lantern',label:'旅行提灯',revision:'3',visibility:'public',token:'[[entity:travel-lantern@3]]'},{kind:'config',id:'lantern-template',label:'提灯规则',revision:'1',visibility:'public',token:'[[config:lantern-template@1]]'},{kind:'data',id:'environment.json',label:'场景环境',revision:'demo-rules',visibility:'kp',token:'[[data:environment.json@demo-rules]]'}];
function proposal(){if($('role').value!=='kp')return;$('checks').hidden=false;$('result').textContent='';$('risk').checked=false;$('risk').disabled=false;$('approve').disabled=$('apply').disabled=true;$('review-title').textContent='旅行提灯 · 改良方案';$('review-copy').textContent='一份可审核的候选配置。这里只演示交互，不写入任何存档。';}
function mount(){chat?.destroy();client?.destroy();session=null;items=[];$('checks').hidden=true;$('result').textContent='';$('risk').checked=false;$('approve').disabled=$('apply').disabled=true;
 const role=$('role').value;
 const transport={async request(path,o={}){if(path.startsWith('ai/references?')){const query=new URLSearchParams(path.split('?')[1]);return {items:references.filter(r=>r.kind===query.get('kind')&&(role==='kp'||r.visibility==='public')&&(r.id+r.label).includes(query.get('q')||'')),hasMore:false};}if(path==='ai/references/resolve')return {items:o.body.tokens.map(token=>{const item=references.find(r=>r.token===token&&(role==='kp'||r.visibility==='public'));if(!item)throw Object.assign(new Error('REFERENCE_STALE'),{code:'REFERENCE_STALE'});return {...item,value:{range:2,fuel:1}};})};if(path.startsWith('ai/sessions?'))return {items:session?[{...session,requestCount:items.length}]:[]};if(path.startsWith('ai/sessions/'))return {session,items};if(path==='ai/commands'){const {op,args,requestId}=o.body;let result={};if(op==='ai.session.create'){session={sessionId:'demo',title:args.title,revision:1,owner:role,archived:false};result=session;}if(op==='ai.session.submit'){const id='demo-'+(++counter);items.push({requestId:id,text:args.text,status:'received'});session.revision++;result={requestId:id,sessionId:'demo'};if(role==='player')$('result').textContent='玩家需求已提交。下一步由 KP 转交和审核。';}if(op==='ai.request.dispatch'){items[items.length-1].status='review_ready';items[items.length-1].response='可以将照明范围从 2 提高到 3，同时每次消耗 2 单位燃料。已有提灯保持原值，建议先试用一场。';items[items.length-1].proposalId='demo-proposal';proposal();}if(op==='ai.session.update'){Object.assign(session,args,{revision:session.revision+1});result=session;}if(op==='ai.request.cancel'){const item=items.find(x=>x.requestId===args.requestId);item.status='cancelled';}return {requestId,status:'committed',result};}return {};}};
 client=new AiClient(transport);client.connected=true;client.view={role,accountId:role,authorityEpoch:'prototype',entities:{}};chat=mountChat($('chat'),client,{listTarget:$('session-list'),onReview:proposal});}
$('role').onchange=mount;$('insert').onclick=()=>{chat.setDraft('我想改良 [[entity:travel-lantern@3]]，让照明更远，但保持合理消耗。',[references[0]]);};
$('risk').onchange=()=>{$('approve').disabled=!$('risk').checked;};$('approve').onclick=()=>{$('result').textContent='已模拟批准；尚未加载。';$('apply').disabled=false;$('approve').disabled=true;$('risk').disabled=true;};$('apply').onclick=()=>{$('result').textContent='已模拟加载：候选配置成为新建实例的版本。真实游戏没有发生改变。';$('apply').disabled=true;items[items.length-1].status='published';chat.select('demo');};mount();
